namespace Archy.Features.Memory.ComposeSessionChangelog;
/// <summary>Produces a deterministic, source-linked changelog without asking a model to reinterpret already validated English diffs.</summary>
public sealed class SessionChangelogComposer:ISessionChangelogComposer { public string Compose(IReadOnlyList<SessionChangelogEntry> entries){ArgumentNullException.ThrowIfNull(entries);if(entries.Any(e=>e is null||string.IsNullOrWhiteSpace(e.TargetStableId)||string.IsNullOrWhiteSpace(e.EnglishDiff)||string.IsNullOrWhiteSpace(e.SummaryVersionId))||entries.Select(e=>e.TargetStableId).Distinct(StringComparer.Ordinal).Count()!=entries.Count)throw new ArgumentException("Changelog entries require unique targets and linked English diffs.",nameof(entries));return string.Join(Environment.NewLine,entries.OrderBy(e=>e.TargetStableId,StringComparer.Ordinal).Select(e=>$"- {e.EnglishDiff} (summary {e.SummaryVersionId}; target {e.TargetStableId})"));}}
